/**
 * 請求書PDF生成モジュール
 * jsPDF + jspdf-autotable + NotoSansJP フォント
 * クライアントサイドで完結
 */

// ===== 画像データ (Base64) =====
const LOGO_OFFICE_B64 = "data:image/png;base64,";
const HANKO_SYOKUIN_B64 = "data:image/png;base64,";

// ===== 自社情報 (SSOT) =====
const OFFICE_INFO = {
    name: '行政書士 中村事務所',
    nameLine1: '行政',
    nameLine2: '中村事務所',
    nameLine3: '書士',
    representative: '中村 宏明',
    postalCode: '160-0023',
    address: '東京都新宿区西新宿7-19-7-402',
    building: '',
    tel: '03-5386-3001',
    fax: '03-5386-3002',
    email: '',
    registrationNumber: 'T4011101011419'
};

// TODO: Phase2で帳票エンジン(report-engine.js)共通化予定

const ESTIMATE_VALID_DAYS = 30;

function pdfFormatCurrency(val) {
    const n = Number(val) || 0;
    return '¥' + n.toLocaleString('ja-JP') + '-';
}

// ===== スキーマ・バリデーション (Data Contract First) =====
function validateEstimateData(data) {
    if (!data) {
        throw new Error("見積データが存在しません。");
    }
    if (!data.customerName || typeof data.customerName !== 'string' || data.customerName.trim() === '') {
        throw new Error("宛名（顧客名）が設定されていません。顧客を選択または登録してください。");
    }
    if (!data.estimateItems || !Array.isArray(data.estimateItems) || data.estimateItems.length === 0) {
        throw new Error("見積明細が登録されていません。");
    }
}

async function generateEstimatePdf(data, btnExportEstimatePdf) {
    const originalHtml = btnExportEstimatePdf ? btnExportEstimatePdf.innerHTML : '';
    if (btnExportEstimatePdf) {
        btnExportEstimatePdf.disabled = true;
        btnExportEstimatePdf.innerHTML = '<i data-lucide="loader" class="spin"></i> 生成中...';
        if (typeof lucide !== 'undefined') lucide.createIcons();
    }

    try {
        // 0. 事前バリデーション (Fail-Fast: 契約違反のデータは即座に停止)
        validateEstimateData(data);

        if (!window.ReportEngine) {
            throw new Error("ReportEngine (report-engine.js) が読み込まれていません。");
        }

        // report-engine を使って jsPDF インスタンスとフォントを初期化
        const doc = await window.ReportEngine.initPDF({
            orientation: 'portrait',
            unit: 'mm',
            format: 'a4'
        });

        // ==========================================
        // 1. 金額の SSOT 計算 (estimateItems から再計算)
        // ==========================================
        let taxableSubtotal = 0;
        let nontaxableSubtotal = 0;

        data.estimateItems.forEach(item => {
            const amt = Number(item.amount) || 0;
            if (item.is_taxable) {
                taxableSubtotal += amt;
            } else {
                nontaxableSubtotal += amt;
            }
        });
        const taxAmount = Math.floor(taxableSubtotal * 0.10);
        const totalAmount = taxableSubtotal + nontaxableSubtotal + taxAmount;

        // ==========================================
        // 2. 基本情報の設定
        // ==========================================
        const today = new Date();
        const validUntil = new Date(today.getTime() + ESTIMATE_VALID_DAYS * 24 * 60 * 60 * 1000);
        
        // 日付フォーマット YYYY年MM月DD日
        const formatDateJP = (d) => `${d.getFullYear()}年${String(d.getMonth() + 1).padStart(2, '0')}月${String(d.getDate()).padStart(2, '0')}日`;
        
        const estimateDateStr = formatDateJP(today);
        const validDateStr = formatDateJP(validUntil);
        const estimateNumber = `EST-${data.caseNumber || 'NEW'}`; // Phase2: 見積履歴管理導入時は estimate_id へ移行予定
        
        const marginL = 20;
        const rightCol = 190;
        let startY = 20;

        // ==========================================
        // 3. 描画 (ヘッダ・ロゴ・宛名等)
        // ==========================================
        // 宛名 (顧客名必須)
        const custName = data.customerName.trim();
        const custTitle = (data.customerTitle || '様').trim();
        doc.setFontSize(14);
        doc.text(`${custName} ${custTitle}`, marginL, startY);
        doc.setLineWidth(0.3);
        doc.line(marginL, startY + 2, 100, startY + 2); // 下線
        
        // タイトル
        doc.setFontSize(22);
        doc.text("御 見 積 書", 105, startY + 15, { align: "center" });
        doc.setLineWidth(0.5);
        doc.line(75, startY + 17, 135, startY + 17);
        
        // 右上情報 (発行日, 有効期限, 番号等)
        doc.setFontSize(10);
        let infoY = startY - 5;
        doc.text(`発行日: ${estimateDateStr}`, rightCol, infoY, { align: "right" });
        infoY += 5;
        doc.text(`有効期限: ${validDateStr}`, rightCol, infoY, { align: "right" });
        infoY += 5;
        doc.text(`見積番号: ${estimateNumber}`, rightCol, infoY, { align: "right" });
        infoY += 5;
        doc.text(`案件番号: ${data.caseNumber || '未採番'}`, rightCol, infoY, { align: "right" });
        if (data.assignee) {
            infoY += 5;
            doc.text(`担当: ${data.assignee}`, rightCol, infoY, { align: "right" });
        }

        // 発行元情報ブロック（ロゴ画像 + 職印）
        // ロゴ画像内に「行政書士中村事務所 + 住所 + TEL/FAX」が含まれているため、アスペクト比を維持して描画し、重複テキストを排除
        const issuerBlockX = rightCol - 75;
        const issuerTopY = startY + 25;

        try {
            const imgProps = doc.getImageProperties(LOGO_OFFICE_B64);
            const ratio = imgProps.width / imgProps.height;
            let drawW = 65;
            let drawH = 65 / ratio;
            if (drawH > 16) {
                drawH = 16;
                drawW = 16 * ratio;
            }
            console.log("Estimate PDF Logo dimensions:", { origW: imgProps.width, origH: imgProps.height, drawW, drawH });
            doc.addImage(LOGO_OFFICE_B64, 'PNG', issuerBlockX, issuerTopY, drawW, drawH);
        } catch (e) {
            console.warn("Logo image error:", e);
            doc.setFontSize(11);
            doc.text(OFFICE_INFO.name || '行政書士 中村事務所', rightCol, issuerTopY, { align: "right" });
            doc.setFontSize(9);
            doc.text(`〒${OFFICE_INFO.postalCode || '160-0023'} ${OFFICE_INFO.address || ''}`, rightCol, issuerTopY + 5, { align: "right" });
            doc.text(`TEL: ${OFFICE_INFO.tel || ''}  FAX: ${OFFICE_INFO.fax || ''}`, rightCol, issuerTopY + 10, { align: "right" });
        }

        // 職印画像（自社ブロック右上に自然に重ねて配置）
        const hankoSize = 22;
        const hankoX = rightCol - hankoSize - 2;
        const hankoY = issuerTopY - 4;
        try {
            doc.addImage(HANKO_SYOKUIN_B64, 'PNG', hankoX, hankoY, hankoSize, hankoSize);
        } catch (e) {
            console.warn("Hanko image error:", e);
        }

        // 挨拶と合計金額
        let summaryY = issuerTopY + 22;
        doc.setFontSize(10);
        doc.text("下記の通り御見積申し上げます。", marginL, summaryY);
        summaryY += 12;
        
        doc.setFontSize(14);
        doc.text("御見積金額合計", marginL, summaryY);
        doc.setFontSize(18);
        doc.text(pdfFormatCurrency(totalAmount), marginL + 50, summaryY);
        
        doc.setLineWidth(0.4);
        doc.line(marginL, summaryY + 2, marginL + 90, summaryY + 2);
        
        summaryY += 12;

        // ==========================================
        // 4. 明細テーブル (jspdf-autotable)
        // ==========================================
        const tableData = data.estimateItems.map(item => [
            item.type,
            item.description,
            item.quantity,
            pdfFormatCurrency(item.unit_price),
            pdfFormatCurrency(item.amount),
            item.is_taxable ? '○' : ''
        ]);

        doc.autoTable({
            startY: summaryY,
            head: [['種別', '内容', '数量', '単価', '金額', '課税']],
            body: tableData,
            theme: 'grid',
            styles: {
                font: 'NotoSansJP',
                fontSize: 9,
                cellPadding: 3,
                lineColor: [200, 200, 200],
                lineWidth: 0.1,
                textColor: [33, 37, 41]
            },
            headStyles: {
                fillColor: [248, 249, 250],
                textColor: [33, 37, 41],
                fontStyle: 'bold',
                halign: 'center'
            },
            columnStyles: {
                0: { halign: 'center', cellWidth: 20 },
                1: { halign: 'left', cellWidth: 'auto' },
                2: { halign: 'right', cellWidth: 15 },
                3: { halign: 'right', cellWidth: 25 },
                4: { halign: 'right', cellWidth: 25 },
                5: { halign: 'center', cellWidth: 12 }
            }
        });

        // ==========================================
        // 5. 合計サマリーテーブル
        // ==========================================
        const finalY = doc.lastAutoTable.finalY + 10;
        
        // もし次のテーブルがページをはみ出す場合は改ページする
        if (finalY + 40 > doc.internal.pageSize.getHeight()) {
            doc.addPage();
        }

        const summaryTableData = [
            ['小計（課税対象）', pdfFormatCurrency(taxableSubtotal)],
            ['消費税 (10%)', pdfFormatCurrency(taxAmount)],
            ['小計（非課税・実費等）', pdfFormatCurrency(nontaxableSubtotal)],
            ['合計', pdfFormatCurrency(totalAmount)]
        ];

        doc.autoTable({
            startY: finalY > doc.internal.pageSize.getHeight() - 40 ? 20 : finalY,
            body: summaryTableData,
            theme: 'plain',
            styles: {
                font: 'NotoSansJP',
                fontSize: 10,
                cellPadding: 2,
                textColor: [33, 37, 41]
            },
            columnStyles: {
                0: { halign: 'right', cellWidth: 130 },
                1: { halign: 'right', cellWidth: 40, fontStyle: 'bold' }
            }
        });

        // ==========================================
        // 6. 備考欄 (固定テキスト)
        // ==========================================
        let remarksY = doc.lastAutoTable.finalY + 15;
        if (remarksY + 30 > doc.internal.pageSize.getHeight()) {
            doc.addPage();
            remarksY = 20;
        }

        doc.setFontSize(10);
        doc.text("【備考】", marginL, remarksY);
        remarksY += 6;
        doc.setFontSize(9);
        const remarks = [
            "・有効期限内にご発注ください",
            "・業務着手後の返金はできません",
            "・上記金額には消費税を含みます"
        ];
        remarks.forEach(text => {
            doc.text(text, marginL + 5, remarksY);
            remarksY += 5;
        });

        // ==========================================
        // 7. 出力処理 (別タブプレビュー表示)
        // ==========================================
        const blob = doc.output('blob');
        const url = URL.createObjectURL(blob);
        const win = window.open(url, '_blank');
        
        if (!win) {
            // ポップアップがブロックされた場合のフォールバックダウンロード
            const safeCustomerName = data.customerName.replace(/[\\/:*?"<>|]/g, '_');
            const filename = `見積書_${safeCustomerName}_${estimateNumber}.pdf`;
            doc.save(filename);
        }

        // メモリリーク防止（60秒後に Blob URL を解放）
        setTimeout(() => {
            try {
                URL.revokeObjectURL(url);
            } catch (e) {}
        }, 60000);

        return doc;

    } catch (e) {
        console.error("見積書生成に失敗しました:", e);
        alert('見積書PDFの生成に失敗しました: ' + e.message);
        throw e;
    } finally {
        if (btnExportEstimatePdf) {
            btnExportEstimatePdf.disabled = false;
            btnExportEstimatePdf.innerHTML = originalHtml;
            if (typeof lucide !== 'undefined') lucide.createIcons();
        }
    }
}

// Global expose
window.generateEstimatePdf = generateEstimatePdf;
window.validateEstimateData = validateEstimateData;
